#!/usr/bin/env python3
"""Condense one captured JSONL session log. argv: <file> [mode] [max-chars]
mode: turns (default) = user/assistant text + tool call one-liners + errors
      tools = tool timeline with wall-clock deltas
"""
import json, sys, datetime

path, mode = sys.argv[1], (sys.argv[2] if len(sys.argv) > 2 else 'turns')
cap = int(sys.argv[3]) if len(sys.argv) > 3 else 400

def ts(e):
    return e.get('timestamp') or (e.get('message') or {}).get('timestamp') or ''

def short(s, n=cap):
    s = ' '.join(str(s).split())
    return s if len(s) <= n else s[:n] + ' …'

entries = []
for line in open(path, encoding='utf-8', errors='replace'):
    line = line.strip()
    if not line: continue
    try: entries.append(json.loads(line))
    except Exception: pass

tool_start = {}
for e in entries:
    t = ts(e)
    typ = e.get('type')
    msg = e.get('message') or {}
    role = msg.get('role') or typ
    if typ == 'queue-operation':
        print(f"[{t}] QUEUED-PROMPT: {short(e.get('content',''), 1200)}")
        continue
    if e.get('attachment'):
        a = e['attachment']
        if a.get('type') == 'hook_success': continue
        print(f"[{t}] ATTACH {a.get('type')}: {short(a.get('content') or a.get('stdout') or '', 300)}")
        continue
    content = msg.get('content')
    if isinstance(content, str):
        if content.strip(): print(f"[{t}] {role.upper()}: {short(content)}")
        continue
    if not isinstance(content, list): continue
    for b in content:
        if not isinstance(b, dict): continue
        bt = b.get('type')
        if bt == 'text' and b.get('text','').strip():
            print(f"[{t}] {role.upper()}: {short(b['text'])}")
        elif bt == 'thinking' and mode == 'think':
            print(f"[{t}] THINK: {short(b.get('thinking',''))}")
        elif bt == 'tool_use':
            tool_start[b.get('id')] = t
            inp = b.get('input') or {}
            key = inp.get('command') or inp.get('file_path') or inp.get('pattern') or inp.get('prompt') or inp.get('skill') or inp.get('query') or ''
            print(f"[{t}] TOOL {b.get('name')}: {short(key, 300)}")
        elif bt == 'tool_result':
            c = b.get('content')
            if isinstance(c, list):
                c = ' '.join(x.get('text','') for x in c if isinstance(x, dict))
            err = b.get('is_error')
            if err or mode == 'tools':
                st = tool_start.get(b.get('tool_use_id'))
                dt = ''
                if st and t:
                    try:
                        d = (datetime.datetime.fromisoformat(t.replace('Z','+00:00')) -
                             datetime.datetime.fromisoformat(st.replace('Z','+00:00'))).total_seconds()
                        dt = f" (+{d:.0f}s)"
                    except Exception: pass
                print(f"[{t}] {'ERROR' if err else 'RESULT'}{dt}: {short(c, 400)}")
