});

ruleTester(check('history-search-on-shallow-clone'), {
  clean: {
    'a walk bounded by a range, and one whose file probes the clone': {
      files: {
        'packs/acme-pack/range.mjs': "const out = git('log', '--reverse', `${base}..HEAD`);\n",
